WITH with_windows AS (SELECT *, LAST_VALUE(revenue) IGNORE NULLS OVER (ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_revenue, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY revenue DESC NULLS LAST) AS revenue_dense_rank FROM store_sales) SELECT DATE_TRUNC('MONTH', sale_date) AS activity_month, AVG(revenue) AS avg_revenue, PERCENTILE_APPROX(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, BIT_AND(units) AS units_bit_and FROM with_windows GROUP BY activity_month;
